function runeLv(r){
  var lvs = r.runes.map(function(x){ var i = RUNE_INFO[x.replace('비셔스의 ','')]; return x.indexOf('비셔스') === 0 ? null : (i ? i.lv : null); });
  if (lvs.some(function(v){ return v === null; })) return null;
  return Math.max.apply(null, lvs);
}
