function fmtMod(o){ return o.replace(/(-?[\d.]+)~(-?[\d.]+)/g, '($1–$2)'); }
function isNeg(o){ return /\s-\d/.test(o) && o.indexOf('피격 회복시간') < 0; }
function splitTerms(q){ return q.toLowerCase().split(/\s+/).filter(function(x){ return x && x !== '룬' && x !== 'rune' && x !== 'ルーン' && x !== '符文'; }); }
function matchAll(hay, terms){ var h = norm(hay); return terms.every(function(x){ return h.indexOf(norm(x)) >= 0; }); }
function rwHay(r){
  var ko = [r.name, r.slot, r.bases || '', r.runes.map(function(x){ return x + ' 룬'; }).join(' '), r.opts.join(' ')].join(' ');
  if (LANG === 'ko') return ko;
  return ko + ' ' + [rwName(r), tSlot(r.slot), r.bases ? tBases(r.bases) : '', r.runes.map(tRuneFull).join(' '), r.opts.map(trMod).join(' ')].join(' ');
}
function cubeHay(r){
  var ko = r.title + ' ' + r.out + ' ' + r.note + ' ' + r.ins.map(function(i){ return i[0]; }).join(' ');
  if (LANG === 'ko') return ko;
  return ko + ' ' + trCube(r.title) + ' ' + trCube(r.out) + ' ' + trCube(r.note) + ' ' + r.ins.map(function(i){ return trCube(i[0]); }).join(' ');
}
