function slotLabel(r){ return r.bases ? tSlot(r.slot) + ' (' + tBases(r.bases) + ')' : (r.slot === W ? t('allWeapons14') : tSlot(r.slot)); }
function upText(x){ var u = RUNE_UP[x]; return u ? t('upText', { r:tRuneFull(u.from), n:u.n }) + (u.extra ? ' + ' + t('xOne', { x:trCube(u.extra) }) : '') : t('lowestRune'); }

function highlight(text, terms){
  var out = esc(text);
  terms.forEach(function(x){
    if (!x) return;
    var safe = esc(x).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    try { out = out.replace(new RegExp('(' + safe + ')', 'gi'), '<mark>$1</mark>'); } catch(e){}
  });
  return out;
}

