/* ================= routing ================= */
function parseHash(){
  var h = location.hash.replace(/^#/, '') || '/';
  var parts = h.split('?'), params = {};
  (parts[1] || '').split('&').forEach(function(kv){ if(!kv) return; var p = kv.split('='); try { params[decodeURIComponent(p[0])] = decodeURIComponent(p[1] || ''); } catch(e){} });
  return { path: parts[0], params: params };
}
function route(){
  var r = parseHash(), p = r.path;
  var name = p.indexOf('/runewords') === 0 ? 'runewords' : p.indexOf('/runes') === 0 ? 'runes' : p.indexOf('/cube') === 0 ? 'cube' : p.indexOf('/map') === 0 ? 'map' : p.indexOf('/search') === 0 ? 'search' : p.indexOf('/items') === 0 ? 'items' : p.indexOf('/mods') === 0 ? 'mods' : p.indexOf('/patch') === 0 ? 'patch' : 'home';
  drawNav(name);
  if (name === 'runewords') { S.query = r.params.q || ''; if (r.params.slot && TABS.indexOf(r.params.slot) >= 0) S.slot = r.params.slot; renderRunewords(); }
  else if (name === 'runes') renderRunes(r.params.q || '');
  else if (name === 'cube') renderCube(r.params.cat || 'all', r.params.q || '');
  else if (name === 'map') renderMap(r.params.town || 'henesys', r.params.edit === '1');
  else if (name === 'search') renderSearch(r.params.q || '');
  else if (name === 'items') renderItems(r.params);
  else if (name === 'mods') renderMods(r.params);
  else if (name === 'patch') renderPatch(r.params);
  else renderHome();
  document.getElementById('gq').value = name === 'search' ? (r.params.q || '') : '';
  var titles = { patch:t('patchTitle'), mods:t('mods'), items:t('items'), runewords:t('runewords'), runes:t('runes'), cube:t('cubeRecipes'), map:t('mapTitle'), search:t('search') };
  document.title = (titles[name] ? titles[name] + ' · ' : '') + 'ENTARIA DB';
}
window.addEventListener('hashchange', function(){ route(); window.scrollTo(0,0); });

