function optStats(o){ return OPT_STAT[o.ko] || []; }
function statKey(line){ var m = line.match(/^(.*?)\s((?:Lv)?[+-].*)$/); return m ? m[1] : line; }
function optRunewords(o){
  if (!o.rel.length) return [];
  if (o.rel[0] === '*SKILL') return ALL.filter(function(r){ return r.opts.some(function(x){ return /Lv\+?\d/.test(x); }); });
  return ALL.filter(function(r){ return r.opts.some(function(x){ return o.rel.indexOf(statKey(x)) >= 0; }); });
}
function optRunes(o){
  if (!o.rel.length || o.rel[0] === '*SKILL') return [];
  return ORDER.filter(function(x){ var i = RUNE_INFO[x]; return i && i.fx.some(function(f){ return f.split(', ').some(function(p){ return o.rel.indexOf(statKey(p)) >= 0; }); }); });
}
function optPotion(o){
  if (!o.immune) return null;
  return CUBE.filter(function(r){ return r.cat === 'immune' && r.note.indexOf('엘리트 ' + o.immune + ' 면역력') >= 0; })[0] || null;
}
