    var groups = (grp === 'all' ? OPTION_GROUPS : OPTION_GROUPS.filter(function(g){ return g[0] === grp; })).map(function(g){ return [g, base.filter(function(o){ return o.group === g[0]; })]; }).filter(function(g){ return g[1].length; });
    var el = document.getElementById('obody');
